-- Pegar en el SQL Editor de Supabase (aiuda-empresas). Se puede correr varias veces.
-- Prospectos de Fagal (Quito) del Prospector del 2026-10-20 y la campaña de contacto en frío.
-- La campaña queda APAGADA: se enciende en Clientes cuando la plantilla esté aprobada por Meta.

create table if not exists prospectos (
  id uuid primary key default gen_random_uuid(),
  organizacion_id uuid not null references organizaciones(id) on delete cascade,
  nombre text not null,
  segmento text,
  angulo_codigo text,
  telefono text,
  telefono_wa text check (telefono_wa is null or telefono_wa ~ '^\+[1-9][0-9]{7,14}$'),
  email text,
  website text,
  direccion text,
  token uuid not null default gen_random_uuid() unique,
  whatsapp_at timestamptz,
  email_at timestamptz,
  respondio_at timestamptz,
  baja_at timestamptz,
  error text,
  created_at timestamptz not null default now()
);
alter table prospectos enable row level security;
create unique index if not exists prospectos_wa_idx on prospectos (organizacion_id, telefono_wa) where telefono_wa is not null;
create unique index if not exists prospectos_email_idx on prospectos (organizacion_id, lower(email)) where email is not null;

create table if not exists campanas_frio (
  organizacion_id uuid primary key references organizaciones(id) on delete cascade,
  activa boolean not null default false,
  por_dia integer not null default 30 check (por_dia between 1 and 200),
  plantilla text not null default 'contacto_inicial',
  asunto text not null,
  cuerpo text not null,
  dias_correo integer not null default 3 check (dias_correo between 1 and 30),
  updated_at timestamptz not null default now()
);
alter table campanas_frio enable row level security;

values ((select id from organizaciones where slug='fagal'), false, 30, 'contacto_inicial',
 'Asesoría legal para {empresa} · {organizacion}',
 E'Estimados {empresa}:\n\nSomos {organizacion}, de Quito, con más de 15 años asesorando a empresas en temas tributarios, laborales, societarios, de protección de datos y UAFE, y de contratación pública.\n\nLe escribimos porque {empresa} figura en fuentes públicas de empresas de {segmento} en Quito. Si le interesa una breve reunión, virtual o presencial, con uno de nuestros abogados para revisar si podemos ayudarle, escríbanos por este enlace y agendamos de inmediato:\n{enlace}\n\nSi prefiere no recibir más mensajes, puede darse de baja aquí:\n{baja}\n\n{organizacion} · Quito, Ecuador',
 3)
on conflict (organizacion_id) do nothing;

on conflict do nothing;

select count(*) as prospectos, count(telefono_wa) as con_whatsapp, count(email) as con_correo from prospectos;
